function C:FetchTweetImage()
  if not coroutine.isyieldable() then spawn(C.FetchTweetImage, self) return end
  local flag = NgoEx.IsNotEmpty(self.tweetDrawable.ImageId)
  self._image.gameObject:SetActive(flag)
  if flag then
    local imageId = self.tweetDrawable.ImageId
    local resource = self._resourceMaster.ResourceList:FirstOrDefault(function(r) return r.FileName == imageId end)
    Settings:addImage(imageId, true)
    if resource == nil then
      Debug.LogError(CONCAT(CONCAT(CONCAT("TWEET MASTER: ", imageId), " の 画像Id がなかったよ "), imageId))
    end
    local image = self._image
    image.sprite = LoadPictures.LoadPictureAsync(resource.FileName, "Poketter")
    local component = self._image.gameObject:GetComponent("Button")
    component:OnClickAsObservable():Subscribe(function(_)
      spawn(function() ImageViewerHelper.OpenImageViewer(resource.FileName) end)
    end):AddTo(component.gameObject)
  end
end

function C:Show()
  self._baseCanvasGroup.alpha = 0
  local _ = self._scrollMillisecond / 1000
  local duration = self._fadeMillisecond / 1000
  local cancellationTokenOnDestroy = self.gameObject:GetCancellationTokenOnDestroy()
  spawn(function() self._baseCanvasGroup:DOFade(1, duration):Play():WithCancellation(cancellationTokenOnDestroy) end)
end

function C:ConvertGigaNumber(number)
  if number > 1000000000 then
    return (TOSTR(IDIV(number, 100000000)) .. "G")
  end
  if number > 1000000 then
    return (TOSTR(IDIV(number, 100000)) .. "M")
  end
  if number > 10000 then
    return (TOSTR(IDIV(number, 1000)) .. "K")
  end
  return TOSTR(number)
end

function C:FavRtMove()
  if not self.tweetDrawable.IsOmote then
    return
  end
  local duration = self._buzzMillisecond / 1000
  if self.tweetDrawable.RtNumber > 0 then
    self._rtText:DOCounter(0, self.tweetDrawable.RtNumber, duration, true):OnComplete(function()
      self._rtText.text = self:ConvertGigaNumber(self.tweetDrawable.RtNumber)
    end):Play()
  end
  if self.tweetDrawable.FavNumber > 0 then
    self._favText:DOCounter(0, self.tweetDrawable.FavNumber, duration, true):OnComplete(function()
      self._favText.text = self:ConvertGigaNumber(self.tweetDrawable.FavNumber)
    end):Play()
  end
end

function C:SetKusoRep()
  for _, kusoRep in EACH(self.tweetDrawable.kusoReps) do
    Object.Instantiate(self._kusoRepPrefab, self._kusoRepRoot.transform):SetData(kusoRep)
